{
  "passageId": "laozi-interpretations",
  "items": [
    {
      "id": "R1",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "패권 경쟁의 혼란기는 한비자가 법치를 통한 부국강병을 추구한 시대적 배경이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "『노자』 해석이 한비자의 법치 사상을 정당화하고 뒷받침하는 논거로 제시된다."
    },
    {
      "id": "R3",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "『노자』와 한비자가 모두 도를 만물의 근원으로 이해한다는 견해의 공통성을 밝힌다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 현상이 도의 영향을 받는다는 설명을 인간 사회의 일의 성패라는 세부 내용으로 구체화한다."
    },
    {
      "id": "R5",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "도의 영원한 존재를 인정하면서도 그것이 모습과 이치의 고정성까지 뜻하지는 않는다고 한계를 설정한다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 고정되어 있지 않다는 성질을 근거로 때와 상황에 따른 유연한 변화를 설명한다."
    },
    {
      "id": "R7",
      "type": "CONDITION",
      "otherName": "",
      "reason": "가변성과 비국소성을 도가 모든 사물의 근거가 될 수 있기 위한 필수 조건으로 연결한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도의 가변성과 비국소성에 관한 설명이 도를 만물의 존재와 본질의 근거로 보는 판단을 뒷받침한다."
    },
    {
      "id": "R9",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "도의 가변성이라는 원리를 인간 사회의 통치술에 가져와 통치술도 고정되어서는 안 된다고 주장한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 개별 법칙의 통합이라는 이해를 근거로 시비 판단의 근거가 된다는 의미를 도출한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도가 개별 법칙을 포괄한다는 사실이 다양한 사건의 판단 기준이 될 수 있다는 설명의 근거이다."
    },
    {
      "id": "R12",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "도가 시비 판단의 기준이라는 원리를 입법이라는 구체적인 정치 활동에 적용한다."
    },
    {
      "id": "R13",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "한비자가 욕망을 사회 혼란의 원인으로 본 『노자』의 견해를 명시적으로 수용한다."
    },
    {
      "id": "R14",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "욕망을 제거해야 하는지를 두고 『노자』와 한비자의 다른 입장을 나란히 제시한다."
    },
    {
      "id": "R15",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "혼란의 원인인 욕망을 없앨 수 없다는 문제에 대해 법을 통한 제어를 대응책으로 제시한다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도의 가변성에 근거한 통치술 논의는 『노자』 해석으로 법치 사상을 뒷받침한 구체적인 사례이다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도에 근거한 입법과 욕망의 법적 제어는 한비자의 법치 사상을 뒷받침하는 해석의 구체적 내용이다."
    },
    {
      "id": "R18",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "인간 삶의 올바른 길이라는 유학의 도 이해가 유학자들이 도가의 도에 주목하게 된 사상적 배경이다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유학의 관점에서 이루어진 『노자』 주석이라는 일반적 설명을 왕안석의 사례로 구체화한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오징의 주석은 송나라 이후 유학자들이 전개한 『노자』 해석의 구체적인 사례이다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "설혜의 주석은 유학의 도를 기반으로 전개된 『노자』 해석의 구체적인 사례이다."
    },
    {
      "id": "R22",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "정치적 갈등 속에서 형성된 개혁 분위기가 왕안석의 『노자주』 저술의 시대적 배경이다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "기를 만물의 물질적 근원으로 본다는 설명을 기의 작용에 의한 사물 형성으로 자세히 풀어 준다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "기와 현상 세계가 변화한다는 원리를 사회 제도와 규범의 갱신 문제에 적용한다."
    },
    {
      "id": "R25",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "원문에서 왕안석은 인위 제거가 사회 안정을 가져온다는 『노자』의 주장을 명시적으로 비판한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "사회 안정을 위한 적극적 개입의 내용을 제도와 규범의 제정에서 현실 변화에 따른 갱신까지 구체화한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유학 이념을 이상 정치의 실현 수단으로 삼는 주장은 『노자』를 유학의 실천적 측면과 결부한 구체적 사례이다."
    },
    {
      "id": "R28",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "오징이 체계화된 도교를 대상으로 주술적인 종교에 불과하다는 가치 평가를 내린다."
    },
    {
      "id": "R29",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "도교에 사람들이 빠지는 것을 경계한 태도가 오징의 『도덕진경주』 저술의 사상적 계기이다."
    },
    {
      "id": "R30",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "노자와 공자 학문의 유사성을 밝히려는 목적을 위해 구절 추가와 구성 재편이라는 수단을 사용한다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "도의 현실화로 만물 생성을 설명하는 원리를 인의예지와 사회 규범 및 질서의 해석에도 적용한다."
    },
    {
      "id": "R32",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인의예지의 출현을 도의 쇠퇴로 보는 『노자』와 도의 현실화로 보는 오징의 견해를 비교한다."
    },
    {
      "id": "R33",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "여러 사상이 합류하는 명나라의 사조가 설혜의 『노자집해』 저술의 시대적·사상적 배경이다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노자가 공자도 존중한 스승이라는 점을 근거로 노자 사상에 대한 오해를 풀어야 한다는 판단을 내린다."
    },
    {
      "id": "R35",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "기존 주석의 불충분함으로 노자 사상이 이단시된 문제에 대해 오해를 불식해야 한다는 대응을 제시한다."
    },
    {
      "id": "R36",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "도를 도덕 본성과 천명으로 이해한 해석이 노자 사상과 유학의 탐구 대상이 같다는 판단을 뒷받침한다."
    },
    {
      "id": "R37",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인의예지를 도의 현실화로 설명하는 오징과 인의 비판을 도덕적 충고로 읽는 설혜의 해석 방식을 비교한다."
    },
    {
      "id": "R38",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "도의 성격을 가변적인 것으로 보는 한비자와 불변하는 것으로 보는 오징의 견해가 다르다."
    },
    {
      "id": "R39",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "도를 물질적 근원인 기로 보는 왕안석과 도덕 본성 및 천명으로 보는 설혜의 견해를 나란히 제시한다."
    },
    {
      "id": "R40",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "한비자와 왕안석은 모두 현실의 변화에 맞추어 통치 방식이나 제도를 바꾸어야 한다는 견해를 보인다."
    },
    {
      "id": "R41",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "오징과 설혜는 모두 노자 사상과 유학이 크게 다르지 않다는 공통된 입장을 취한다."
    },
    {
      "id": "R42",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "『노자』를 법치 사상과 결부한 한비자와 유학의 이념에 결부한 후대 유학자들의 해석 관점을 비교한다."
    }
  ]
}

